effect.shader:
const float TAU = 6.28318530718;

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 offset = (acScreenNorm - center) * vec2(acAspect, 1.0);
    float radius = length(offset) / max(zoom, 0.01);
    float angle = atan(offset.y, offset.x) + radians(spin);

    float segment = TAU / max(sides, 2.0);
    angle = mod(angle, segment);
    // Dobra a fatia ao meio. É este `abs` que faz o desenho espelhar em vez de
    // apenas se repetir — sem ele o resultado é um ventilador, não um
    // caleidoscópio.
    angle = abs(angle - segment * 0.5);

    vec2 warped = vec2(cos(angle), sin(angle)) * radius;
    vec2 sampleUv = warped / vec2(acAspect, 1.0) + center;
    sampleUv = clamp(sampleUv, 0.0, 1.0);

    fragColor = mix(original, texture(inputImg, sampleUv), amount);
}
